    /// The error reported for I/O on an invalidated blob handle. Matches
    /// what SQLite itself returns (`SQLITE_ABORT`) for calls that reach it.
    #[inline]
    fn abort_error() -> Error {
        Error::SqliteFailure(
            ffi::Error::new(ffi::SQLITE_ABORT),
            Some("blob handle is invalid".to_owned()),
        )
    }

    /// Return the invalidation error if this handle is known to be aborted.
    #[inline]
    fn check_valid(&self) -> Result<()> {
        if self.poisoned.get() {
            Err(Self::abort_error())
        } else {
            Ok(())
        }
    }

    /// Like `check_valid`, but also asks SQLite when the handle is not yet
    /// known to be invalid. Used by operations that would otherwise return
    /// without calling into SQLite (and would thus never notice that the
    /// underlying row was updated or deleted through this connection).
    ///
    /// A zero-length read is a no-op on a valid handle, but SQLite answers
    /// it with `SQLITE_ABORT` on an invalidated one.
    #[inline]
    fn probe_validity(&self) -> Result<()> {
        self.check_valid()?;
        let mut byte = 0u8;
        let rc = unsafe { ffi::sqlite3_blob_read(self.blob, (&raw mut byte).cast(), 0, 0) };
